<?php
/** TEMP PS S1688 mk — v0.4: f=laukas — Sender laukas PS_HERO_GYV (šuniui/katei) + terra visi 18 laukų vienu PATCH (IMG = ps-relaunch/12466.jpg); f=kurti — 3 testinės kampanijos CALC/PRODUCT/GENERIC v0.4 į PS_TEST (from „Petshop.lt", reply terra@petshop.lt) ir siuntimas. */
add_action('init', function(){
  if (!isset($_GET['ps_s1688mk'])) return; global $wpdb; $o=array('v'=>'S1688 mk'); $f=$_GET['ps_s1688mk'];
  $tok=Petshop_Sender_Adapter::get_stored_token('marketing');
  $api=function($m,$p,$b=null) use($tok){ $a=array('method'=>$m,'timeout'=>25,'headers'=>array('Authorization'=>'Bearer '.$tok,'Accept'=>'application/json','Content-Type'=>'application/json')); if($b!==null) $a['body']=wp_json_encode($b);
    $r=wp_remote_request('https://api.sender.net/v2'.$p,$a); if(is_wp_error($r)) return array('code'=>0,'err'=>$r->get_error_message()); return array('code'=>wp_remote_retrieve_response_code($r),'body'=>json_decode(wp_remote_retrieve_body($r),true)); };
  if($f==='laukas'){
    $r=$api('GET','/fields?limit=100'); $yra=array(); foreach((array)($r['body']['data']??array()) as $x) $yra[$x['title']]=1;
    if(!isset($yra['PS_HERO_GYV'])){ $c=$api('POST','/fields',array('title'=>'PS_HERO_GYV','type'=>'text')); $o['gyv']=$c['code']; } else $o['gyv']='buvo';
    $t=Petshop_Relaunch::t(); $row=$wpdb->get_row("SELECT * FROM $t WHERE email='terra@gyvunai.lt'",ARRAY_A); $duom=json_decode($row['duomenys'],true); $up=wp_upload_dir();
    $fl=array('PS_HERO_SEG'=>'calc','PS_HERO_PAV'=>$duom['pav'],'PS_HERO_KAINA'=>number_format((float)$duom['kaina'],2,',','').' €','PS_HERO_IMG'=>$up['baseurl'].'/ps-relaunch/12466.jpg','PS_HERO_URL'=>$duom['url'],'PS_HERO_GYV'=>'šuniui');
    foreach($duom['eilutes'] as $i=>$e){ $n=$i+1; $fl["PS_HERO_KG$n"]=$e['kg'].' kg'; $fl["PS_HERO_EUR$n"]='nuo '.$e['eur_nuo'].' €'; $fl["PS_HERO_INFO$n"]=$e['g'].' g/d · maišo užtenka '.$e['d'].' d.'; $fl["PS_HERO_U$n"]=$e['url']; }
    $p=$api('PATCH','/subscribers/terra%40gyvunai.lt',array('fields'=>$fl)); $o['patch']=$p['code']; $g=$api('GET','/subscribers/terra%40gyvunai.lt'); $o['cols_n']=count($g['body']['data']['columns']??array()); $o['status']=$g['body']['data']['status']['email']??null;
  } else {
    $K=array(
      'calc'=>array('t'=>'TEST relaunch CALC v0.4','s'=>'Kiek kainuoja jūsų augintinio maistas per dieną?','p'=>'Pavyzdys su jums pažįstamu maistu – {{ps_hero_eur1}} per dieną.','h'=>''),
      'product'=>array('t'=>'TEST relaunch PRODUCT v0.4','s'=>'Petshop.lt atsinaujino – pradėkime nuo jūsų maisto','p'=>'{{ps_hero_pav}} – turime, {{ps_hero_kaina}}. Ir naujas įrankis: priminimas, kai maišas baigiasi.','h'=>''),
      'generic'=>array('t'=>'TEST relaunch GENERIC v0.4','s'=>'Petshop.lt atsinaujino – kas pasikeitė jūsų pirkiniams','p'=>'Ta pati parduotuvė nuo 2010 m., nauja svetainė, jūsų užsakymų istorija išsaugota.','h'=>''));
    $g=$api('GET','/groups/bDxp2q')['body']['data']??array(); $o['aktyviu']=$g['active_subscribers']??null;
    foreach($K as $k=>$c){ $b=array('title'=>$c['t'].' '.date('H:i'),'subject'=>$c['s'],'from'=>'Petshop.lt','reply_to'=>'terra@petshop.lt','content_type'=>'html','content'=>base64_decode($c['h']),'groups'=>array('bDxp2q'),'preheader'=>$c['p']);
      $r=$api('POST','/campaigns',$b); $id=$r['body']['data']['id']??''; $o[$k]=array('kurti'=>$r['code'],'id'=>$id,'err'=>$r['body']['errors']??null);
      if($id && (int)($g['active_subscribers']??0)===1){ $s=$api('POST','/campaigns/'.$id.'/send'); $o[$k]['send']=$s['code'].' '.wp_json_encode($s['body']['message']??$s['body']); } }
  }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
});
